def is_multiply_prime(a):
    def get_primes(n):
        primes = []
        for i in range(2, n + 1):
            if all(i % j != 0 for j in range(2, int(i ** 0.5) + 1)):
                primes.append(i)
        return primes

    primes = get_primes(a)

    count = 0
    temp_a = a

    while temp_a > 1:
        found_prime = False
        for p in primes:
            if temp_a % p == 0 and temp_a // p < temp_a:
                temp_a //= p
                count += 1
                found_prime = True
                break

        if not found_prime:
            return False

    return count == 3

